entries[65637] = { ["name"] = "Great Red Elekk", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Great Red Elekk.\n\"Never seen in Nagrand, the first red elekk calves were born in Azeroth after the Exodar's arrival. Some breeders theorize that the unique coloration is somehow caused by the same radiation which ravaged Bloodmyst Isle.\"\nVendor:\nIrisee\nZone:\nIcecrown\nCost:\n500" }
entries[65638] = { ["name"] = "Swift Moonsaber", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Swift Moonsaber.\n\"Many night elves revere these proud mounts because their shimmering coats symbolize the goddess of the moon, Elune.\"\nVendor:\nRook Hawkfist\nZone:\nIcecrown\nCost:\n500" }
entries[65639] = { ["name"] = "Swift Red Hawkstrider", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Swift red Hawkstrider.\n\"What do you mean is it dyed? Oh, the bird. We did touch up the red just a little. -Trellis Morningsun\"\nVendor:\nTrellis Morningsun\nZone:\nIcecrown\nCost:\n500" }
entries[65640] = { ["name"] = "Swift Gray Steed", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Swift Gray Steed.\n\"A veteran of some of the toughest battles fought by the Argent Crusade.\"\nVendor:\nCorporal Arthur Flew\nZone:\nIcecrown\nCost:\n500" }
entries[65641] = { ["name"] = "Great Golden Kodo", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Great Golden Kodo.\n\"An alpha member of the herd, this kodo is a prime example of the mighty creatures which thunder through the Southern Barrens.\"\nVendor:\nDoru Thunderhorn\nZone:\nIcecrown\nCost:\n500" }
entries[65642] = { ["name"] = "Turbostrider", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Turbostrider.\n\"The mirror's not so you can look back, but so your foes can see something besides your tailpipes. -Rillie Spindlenut\"\nVendor:\nRillie Spindlenut\nZone:\nIcecrown\nCost:\n500" }
entries[65643] = { ["name"] = "Swift Violet Ram", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Swift Violet Ram.\n\"The Barak Tor'ol ram's thick bony skull and massive horns make it the ideal mount for charging through groups of armored enemies.\"\nVendor:\nDerrick Brindlebeard\nZone:\nIcecrown\nCost:\n500" }
entries[65644] = { ["name"] = "Swift Purple Raptor", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Swift Purple Raptor.\n\"Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become mount, guardian, and friend.\"\nVendor:\nSamamba\nZone:\nIcecrown\nCost:\n500" }
entries[65645] = { ["name"] = "White Skeletal Warhorse", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable White Skeletal Warhorse.\n\"When fallen heroes are raised into undeath, so too are their horses.\"\nVendor:\nEliza Killian\nZone:\nIcecrown\nCost:\n500" }
